// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzzed params: an address 'from' and a uint256 value v and a boolean shouldRevert
    // and single recipient index encoded via uint256 to allow fuzzing _tos[0]
    function testFuzz_property(address from, uint256 v, address tosAddr, bool shouldRevert) public {
        // keep tosAddr non-zero to make a valid callee address; allow any other values
        vm.assume(tosAddr != address(0));
        // deploy a helper recorder/reverter that implements transferFrom(address,address,uint256)
        Helper h = new Helper();
        // configure helper to revert or succeed based on fuzzed boolean
        h.setShouldRevert(shouldRevert);

        address[] memory tos = new address[](1);
        tos[0] = address(h);

        // call transfer and observe whether it reverts
        bool ok;
        try c.transfer(from, address(h), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): the reference contract always reverts (ok == false)
        // whenever the callee reverts (shouldRevert == true). The mutant that removed the require
        // would return true (ok == true) even when shouldRevert == true. Thus we assert that if
        // shouldRevert is true then this call did not succeed.
        assertTrue(!(shouldRevert && ok));
    }
}

// Helper that exposes the exact signature transferFrom(address,address,uint256)
// and can be toggled to revert to simulate a failing callee. It also records calls
// (not required by the assertion but provided as the observable callee).
contract Helper {
    bool public shouldRevert;
    // record last call arguments
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;
    uint256 public callCount;

    function setShouldRevert(bool r) public {
        shouldRevert = r;
    }

    // must match selector: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        callCount += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        if (shouldRevert) {
            revert("helper revert");
        }
        return true;
    }
}
